import Defaults
import Foundation

/// UI-testing fixture seam (issue #3 UI tests). When the app is launched with
/// `-WorkroomUITestFixture 1`, `AppStore` loads this deterministic set of fake projects and
/// workrooms instead of reading the developer's real `~/.config/workroom`. The XCUITests
/// (`WorkroomAppUITests`) pass that flag so they're hermetic — they never touch real projects,
/// never depend on what happens to be configured on the machine, and run the same everywhere.
///
/// The fixture targets point at freshly-created temp directories so their terminals still spawn a
/// real login shell (libghostty needs a valid working directory) — the surface mounts and appears
/// in the accessibility tree exactly as it would for a real workroom, which is what the split-pane
/// tests assert on. The app remains a normal app: a regular user never passes the flag, so this
/// code is inert in production.
enum UITestFixture {
  /// The launch-argument / `UserDefaults` key the tests set (highest-priority argument domain).
  static let defaultsKey = "WorkroomUITestFixture"

  /// **DEBUG-only, by construction.** Every fixture flag below reads through `flag`/`number`/`text`,
  /// and outside a Debug build they return the inert default without touching `UserDefaults` at all.
  ///
  /// The flags are read from `UserDefaults.standard`, which is the app's *persisted* domain and not
  /// just the launch-argument domain the tests use. So without this gate a single
  /// `defaults write <bundle id> WorkroomUITestFixture -bool YES` latched a shipping build into
  /// fixture mode permanently: fake projects instead of the user's real `~/.config/workroom`,
  /// `applyFixtureDefaults` overwriting their inspector and diff-mode preferences on every launch,
  /// and `.terminateNow` on quit skipping the graceful run-command teardown — with no in-app way
  /// back out. Several flags (`agentStub`, `forceWhatsNew`, `updateAvailableVersion`) are read
  /// WITHOUT consulting `isActive`, so gating `isActive` alone would not have been enough; the gate
  /// belongs on the reads.
  ///
  /// Nothing in the test suite loses anything: both `WorkroomAppTests` and `WorkroomAppUITests` build
  /// against the Debug configuration (`project.yml`), which is the only one that defines `DEBUG`.
  private static var enabled: Bool {
    #if DEBUG
      return true
    #else
      return false
    #endif
  }

  /// A fixture-namespaced boolean. `bool(forKey:)` rather than `Defaults` on purpose — it coerces the
  /// STRING an argument-domain value arrives as (`-WorkroomUITestFixture 1` stores `"1"`), which a
  /// typed `Defaults` read would reject. See `applyFixtureDefaults` for the trap that implies.
  private static func flag(_ key: String) -> Bool {
    enabled && UserDefaults.standard.bool(forKey: key)
  }

  private static func number(_ key: String) -> Int {
    enabled ? UserDefaults.standard.integer(forKey: key) : 0
  }

  private static func text(_ key: String) -> String? {
    enabled ? UserDefaults.standard.string(forKey: key) : nil
  }

  /// Whether the app was launched in UI-test fixture mode. Always `false` in a release build.
  static var isActive: Bool {
    flag(defaultsKey)
  }

  /// Where a session-restore UI test wants its `session.json` (`-WorkroomUITestSessionFile <path>`).
  ///
  /// **In fixture mode the session store is a no-op unless this is set** (see
  /// `SessionStore.forCurrentEnvironment`). That default-off posture is not optional: the app's
  /// session file is scoped by bundle id, so without it the 30-odd existing UI tests would each write
  /// over the DEVELOPER's own `Workroom Dev` session — and the fixture's temp-directory workrooms
  /// would then be restored into a real launch.
  static var sessionFilePath: String? {
    guard isActive else { return nil }
    return text("WorkroomUITestSessionFile")
  }

  /// A fake `$HOME` holding seeded agent session stores, for the resume-offer UI tests
  /// (`-WorkroomUITestAgentSessionRoot <path>`; the test writes `<path>/.claude/projects/…` and
  /// `<path>/.codex/sessions/…`).
  ///
  /// **Default-off, exactly like `sessionFilePath`** (see `AgentSessionIndex.forCurrentEnvironment`):
  /// with no path supplied, agent discovery does nothing at all in fixture mode. Without that, the
  /// existing UI tests would read the DEVELOPER's real `~/.claude` and `~/.codex`, so whether a test
  /// passed would depend on which directories they happened to have talked to an agent in that day.
  static var agentSessionRoot: String? {
    guard isActive else { return nil }
    return text("WorkroomUITestAgentSessionRoot")
  }

  /// When set (`-WorkroomUITestNoProjects 1`), the fixture loads an EMPTY project list — the
  /// fresh-install / nothing-configured state. Used by `NewWorkroomDialogUITests` to assert File ▸
  /// New Workroom is disabled when there's nothing to pick (issue #81 D3).
  static var noProjects: Bool {
    flag("WorkroomUITestNoProjects")
  }

  /// When set (`-WorkroomUITestJJProject 1`), the fixture's project reports itself as **jj** instead of
  /// git.
  ///
  /// The fixture has always fed jj-SHAPED status — `jjWorkingCopy`, with `@`'s change-id, commit-id,
  /// bookmarks and description — while declaring the project `vcs: "git"`, because git is what makes the
  /// sidebar's root row render plainly and no real VCS call is ever made either way. That was invisible
  /// until the VCS toolbar started wording itself per backend: it read "Current Branch" over jj data, and

/// stays exactly as narrow and as greppable as it was: an AI-*suggested* command is never
/// auto-executed. The distinction is the provenance, not the mechanism. `sendText` carries a string
/// a model produced, which nobody has read yet. This carries a compile-time constant
/// (`AgentInvocationBuilder.resume`) behind a button labelled Resume — the click is the review.
///
/// Callers must confirm the pane is pristine first (`AgentResumeCoordinator.paneReceivedInput`),
/// since appending to a half-typed line would run something else entirely.
///
/// The submit byte is `\r`, the same thing Return puts on the wire. If a libghostty version ever
/// filters control bytes out of the text path this is where it would show up — as a command typed
/// but not run — and the fix is to send Return through `ghostty_surface_key` instead.
func sendCommandLine(_ commandLine: String) {
  guard surface != nil, !commandLine.isEmpty else { return }
  sendText(commandLine + "\r")
}

/// **Fixture-only.** Expose the visible screen text to the accessibility tree so an XCUITest can
/// assert what a terminal actually did.
///
/// A libghostty surface renders through Metal, so its contents are invisible to XCUITest — which
/// leaves whole behaviours unassertable end to end. The one that forced this: issue #145 types a
/// command in and submits it with `\r`, and if a libghostty version ever filtered control bytes out
/// of the text path the command would be typed and never run. That failure is silent from the
/// outside and there is no unit test for it, because the behaviour under test belongs to the engine.
///
/// Gated on `UITestFixture.isActive`, which is itself `#if DEBUG` — a release build reads nothing
/// and publishes nothing. `VIEWPORT` is the visible screen only, never the scrollback.
override func isAccessibilityElement() -> Bool {
  UITestFixture.isActive ? true : super.isAccessibilityElement()
}

override func accessibilityValue() -> Any? {
  guard UITestFixture.isActive else { return super.accessibilityValue() }
  return readText(tag: GHOSTTY_POINT_VIEWPORT) ?? ""
}

override func accessibilityIdentifier() -> String {
  UITestFixture.isActive ? "terminal.surface" : super.accessibilityIdentifier()
}

/// Fired the FIRST time this pane sees real user input, and never again.
///
/// "Real" means a keystroke, an IME commit or a paste — the AppKit entry points. Text this app
/// writes in itself (`sendText` / `sendCommandLine`) goes straight to libghostty and does not pass
/// through them, which is what stops the Resume action from cancelling its own offer.
var onFirstUserInput: (() -> Void)?
private var didReportUserInput = false

private func noteUserInput() {
  guard !didReportUserInput else { return }
